fn legacy_rc4_uses_object_and_generation_and_truncates_to_ten_bytes() {
    let handler = standard_handler(R2.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(None, trailer.id()).unwrap();

    // 既知の R2 ファイル鍵に番号をリトルエンディアンで連結し、Python の hashlib で照合した。
    for (number, generation, expected) in [
        (7, 0x1234, b"\xf1\x2f\xa0\xa4\x93\xe0\x98\x62\xb8\x9f"),
        (8, 0x1234, b"\xac\x0b\xec\xab\xa7\xe5\x74\x66\x52\x21"),
        (7, 0x1235, b"\x78\x93\xd9\x0c\x35\x7a\x5d\x7f\xaa\x6d"),
    ] {
        let target = indirect(number, generation, EncryptedValueKind::String);
        let ObjectDecryption::Rc4(key) = auth.object_decryption(target).unwrap() else {
            panic!("V1 の文字列には RC4 の鍵が必要");
        };
        assert_eq!(key.as_bytes(), expected);
    }
}

fn algorithm_one_uses_only_the_low_three_object_number_bytes() {
    let handler = standard_handler(R2.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(None, trailer.id()).unwrap();

    // 0xff_ffff は 3 バイトの上限。0x100_0000 の下位 3 バイトは 00 00 00。
    for (number, generation, expected) in [
        (
            0xff_ffff,
            0xffff,
            b"\x42\x30\xf5\x89\xe6\xb9\x12\x90\x8f\xad",
        ),
        (
            0x100_0000,
            0xffff,
            b"\x92\x2d\x06\x64\x3c\x7b\x68\x91\x6d\xb8",
        ),
        (
            0xab_cdef,
            0x1234,
            b"\xf6\x64\x60\x5f\x8d\x58\x8d\xe7\xb2\x13",
        ),
        (
            0x1ab_cdef,
            0x1234,
            b"\xf6\x64\x60\x5f\x8d\x58\x8d\xe7\xb2\x13",
        ),
    ] {
        let target = indirect(number, generation, EncryptedValueKind::Stream);
        let ObjectDecryption::Rc4(key) = auth.object_decryption(target).unwrap() else {
            panic!("V1 のストリームには RC4 の鍵が必要");
        };
        assert_eq!(key.as_bytes(), expected);
    }
}

fn aesv3_reuses_the_same_authenticated_file_key_for_distinct_objects() {
    let handler = standard_handler(R5.as_bytes());
    let auth = handler.authenticate(Some(b"user-r5"), None).unwrap();
    let file_key = auth.key().as_aes256().unwrap();

    for (number, generation, kind) in [
        (7, 0, EncryptedValueKind::String),
        (0x100_0000, 8, EncryptedValueKind::Stream),
    ] {
        let target = indirect(number, generation, kind);
        let ObjectDecryption::Aes256(key) = auth.object_decryption(target).unwrap() else {
            panic!("AESV3 の場合はファイル暗号鍵を使う");
        };
        assert!(std::ptr::eq(key, file_key));
    }
}

fn stream_and_string_filters_select_salted_aes128_and_unsalted_rc4() {
    let source = R4_CLEAR_METADATA
        .replace("/CF << /StdCF", "/CF << /Legacy << /CFM /V2 >> /StdCF")
        .replace("/StrF /StdCF", "/StrF /Legacy");
    let handler = standard_handler(source.as_bytes());
    let trailer = parse_trailer(TRAILER);
    let auth = handler.authenticate(Some(b"user"), trailer.id()).unwrap();

    let stream = indirect(7, 0x1234, EncryptedValueKind::Stream);
    let ObjectDecryption::Aes128(aes) = auth.object_decryption(stream).unwrap() else {
        panic!("/StmF の AESV2 が選ばれる");
    };
    let string = indirect(7, 0x1234, EncryptedValueKind::String);
    let ObjectDecryption::Rc4(rc4) = auth.object_decryption(string).unwrap() else {
        panic!("/StrF の V2 が選ばれる");
    };

    // 同じ ObjectId と既知の R4 ファイル鍵で、sAlT の有無だけを変えて hashlib で照合した。
    assert_eq!(
        aes.as_bytes(),
        b"\x1b\x66\xd7\xe5\xff\xda\x93\xe9\xbb\x90\x89\x2a\xb0\xe0\x50\x27"
    );
    assert_eq!(
        rc4.as_bytes(),
        b"\xa8\x1a\xbb\xe4\x02\x51\x16\xeb\xda\x01\xd9\x65\x26\x39\xdd\xee"
    );
}

fn identity_and_no_encryption_method_return_no_key() {
    let trailer = parse_trailer(TRAILER);
    for selectors in [
        "/StrF /Identity /StmF /Identity",
        "",
        "/StrF /Clear /StmF /Default",
    ] {
        let source = R4_CLEAR_METADATA
            .replace("/StmF /StdCF /StrF /StdCF", selectors)
            .replace(
                "/CF << /StdCF",
                "/CF << /Clear << /CFM /None >> /Default << >> /StdCF",
            );
        let handler = standard_handler(source.as_bytes());
        let auth = handler.authenticate(Some(b"user"), trailer.id()).unwrap();

        for kind in [EncryptedValueKind::Stream, EncryptedValueKind::String] {
            let target = indirect(7, 0, kind);
            assert!(matches!(
                auth.object_decryption(target).unwrap(),
                ObjectDecryption::None
            ));
        }
    }
}

fn undefined_stream_and_string_filter_fail_during_dictionary_parsing() {
    for (selector, key) in [("/StmF", EncryptKey::StmF), ("/StrF", EncryptKey::StrF)] {
        let source = R4_CLEAR_METADATA.replace(
            &format!("{selector} /StdCF"),
            &format!("{selector} /Unknown"),
        );
        assert_eq!(
            encrypt_err(source.as_bytes()).kind(),
            &EncryptErrorKind::UndefinedCryptFilter {
                key,
                name: PdfName::from("Unknown")
            },
        );
    }
}

